/// Parse POSIX-style argv into Options.  args[0] is the program name
/// (skipped); `--` ends flag parsing; every matched flag sets its
/// field, coerced inline (the Dhall type never sees argv strings).
/// Accepted spellings: exact short/long tokens, argumentless short
/// clusters (-la == -l -a; a Value short never clusters) and inline
/// --long=value for Value longs.  Text operands are gpa-owned
/// dupes on success; on error earlier dupes are not freed (same
/// discipline as the hand parsers this replaces).
pub fn parsePosix(args: []const []const u8, gpa: Allocator) ParseError!Options {
    _ = gpa;
    var o = Options{};
    var i: usize = 1;
    var after_ddash = false;
    while (i < args.len) : (i += 1) {
        const a = args[i];
        if (after_ddash) {
            std.debug.print("fx-uname: unexpected operand '{s}'\n", .{ a });
            return error.UnexpectedOperand;
        }
        if (std.mem.eql(u8, a, "--")) {
            after_ddash = true;
            continue;
        }
        var matched = false;
        if (a.len > 2 and a[0] == '-' and a[1] != '-') {
            var cluster = true;
            for (a[1..]) |ch| {
                var letter_matched = false;
                if (ch == 'a') {
                    o.all = true;
                    letter_matched = true;
                }
                if (ch == 's') {
                    o.kernel = true;
                    letter_matched = true;
                }
                if (ch == 'n') {
                    o.nodename = true;
                    letter_matched = true;
                }
                if (ch == 'r') {
                    o.release = true;
                    letter_matched = true;
                }
                if (ch == 'v') {
                    o.version = true;
                    letter_matched = true;
                }
                if (ch == 'm') {
                    o.machine = true;
                    letter_matched = true;
                }
                if (ch == 'o') {
                    o.os = true;
                    letter_matched = true;
                }
                if (!letter_matched) cluster = false;
            }
            if (cluster) continue;
        }
        if (!matched and (std.mem.eql(u8, a, "-a") or std.mem.eql(u8, a, "--all"))) {
            o.all = true;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-s") or std.mem.eql(u8, a, "--kernel-name"))) {
            o.kernel = true;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-n") or std.mem.eql(u8, a, "--nodename"))) {
            o.nodename = true;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-r") or std.mem.eql(u8, a, "--release"))) {
            o.release = true;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-v"))) {
            o.version = true;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-m") or std.mem.eql(u8, a, "--machine"))) {
            o.machine = true;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-o") or std.mem.eql(u8, a, "--operating-system"))) {
            o.os = true;
            matched = true;
        }
        if (!matched) {
            if (a.len > 1 and a[0] == '-') {
                std.debug.print("fx-uname: unknown option '{s}'\n", .{ a });
                return error.UnknownOption;
            }
            std.debug.print("fx-uname: unexpected operand '{s}'\n", .{ a });
            return error.UnexpectedOperand;
        }
    }
    return o;
}

pub fn usage() []const u8 {
    return "usage: fx-uname [OPTIONS]\n";
