test "cli_uname: empty argv yields the dflt defaults" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const gpa = arena_state.allocator();
    const argv = [_][]const u8{ "fx-uname" };
    const o = try parsePosix(&argv, gpa);
    try std.testing.expectEqual(false, o.all);
    try std.testing.expectEqual(false, o.kernel);
    try std.testing.expectEqual(false, o.machine);
    try std.testing.expectEqual(false, o.nodename);
    try std.testing.expectEqual(false, o.os);
    try std.testing.expectEqual(false, o.release);
    try std.testing.expectEqual(false, o.version);
}

